def determinar_rol_para_poema(user, autor):
    """
    Determina de forma precisa cuál de los 6 bancos poéticos corresponde al usuario.
    """
    if user and user.is_superuser:
        return 'SUPERADMIN'
    if not autor:
        return 'DOCENTE_UABC'
    if getattr(autor, 'es_soporte', False) or autor.rol_facultad in ['SOPORTE', 'DEP_TEC'] or getattr(autor, 'es_operador_tecnico', False):
        return 'SOPORTE'
    if getattr(autor, 'es_auxiliar', False) or autor.rol_facultad == 'AUX_INV':
        return 'AUXILIAR'
    if autor.rol_facultad == 'INV_IND' or 'independiente' in (autor.institucion_origen or '').lower():
        return 'INVESTIGADOR'
    if autor.es_externo or autor.rol_facultad == 'EXT':
        return 'DOCENTE_EXTERNO'
    return 'DOCENTE_UABC'


def obtener_poema_cumpleanos_usuario(user, autor, anio=None):
    """
    Retorna el poema anual único correspondiente al rol y año de nacimiento/celebración.
    Selección determinista por año para evitar que cambie en cada recarga de página el mismo día.
    """
    if anio is None:
        anio = timezone.localdate().year

    rol_clave = determinar_rol_para_poema(user, autor)
    lista_poemas = POEMAS_CUMPLEANOS_POR_ROL.get(rol_clave, POEMAS_CUMPLEANOS_POR_ROL['DOCENTE_UABC'])

    user_id = user.id if user else 1
    autor_id = autor.id if autor else user_id

    # Fórmula determinista anual: cambia cada año pero es estable en todas las visitas del mismo año
    seed = (user_id * 19 + autor_id * 7 + anio * 37) % len(lista_poemas)
    poema = lista_poemas[seed]

    return {
        'id_poema': seed + 1,
        'rol_clave': rol_clave,
        'rol_nombre': NOMBRES_ROLES_POEMAS.get(rol_clave, 'Comunidad FCA'),
        'titulo': poema['titulo'],
        'versos': poema['versos'],
        'dedicatoria': poema.get('dedicatoria', 'Con profundo aprecio institucional en tu día'),
        'firma': 'Dirección de la Facultad de Contaduría y Administración • Universidad Autónoma de Baja California',
        'anio': anio
    }
